def verify(img, db, dbx):
    h = sha256(img.data)
    if h in dbx:
        return False          # A: image hash revoked
    for cert in img.chain:    # leaf, then CA
        if cert in dbx:
            return False      # B/C: a cert in the chain revoked
    if h in db:
        return True           # allowed by hash
    for cert in img.chain:
        if cert in db:
            return True       # allowed by a trusted cert
    return False              # not in db at all

import hashlib
H = lambda b: hashlib.sha256(b).hexdigest()[:8]

# Toy images: bytes plus the certificate chain that signed them (leaf, CA).
# Signature checking itself is assumed done; we model only the db/dbx policy.
bootmgr_2019 = {"name": "bootmgr 2019", "data": b"bm-2019",
                "chain": ["Win Prod 2019 leaf", "Win Prod PCA 2011"]}
bootmgr_2022 = {"name": "bootmgr 2022", "data": b"bm-2022",
                "chain": ["Win Prod 2022 leaf", "Win Prod PCA 2011"]}
bootmgr_2024 = {"name": "bootmgr 2024", "data": b"bm-2024",
                "chain": ["Win 2024 leaf", "Windows UEFI CA 2023"]}

db  = {"Win Prod PCA 2011", "Windows UEFI CA 2023"}
dbx = {H(b"bm-2019")}                # one vulnerable binary revoked by hash

def verify_bad(img):                 # BUG: only looks at db
    return any(c in db for c in img["chain"])

def verify_good(img):                # UEFI rule: allowed by db AND not in dbx
    if H(img["data"]) in dbx:
        return False                 # A: image hash revoked
    if any(c in dbx for c in img["chain"]):
        return False                 # B/C: any cert in the chain revoked
    return H(img["data"]) in db or any(c in db for c in img["chain"])

for label, x in [("hash in dbx", None), ("CA in dbx", "Win Prod PCA 2011")]:
    if x: dbx.add(x)
    print(f"-- {label}")
    for img in (bootmgr_2019, bootmgr_2022, bootmgr_2024):
        print(f"{img['name']}: bad={verify_bad(img)!s:5} good={verify_good(img)}")

# Toy model of the fail-open pattern behind Baton Drop (CVE-2022-21894).
# Made-up names; this is not Windows code and no real option is shown.
DANGEROUS = {"allow_unsigned", "skip_checks"}

def load_policy(memory, policy_addr):
    # the signed Secure Boot policy sits in memory the boot app reads
    return memory.get(policy_addr)          # None if that memory is gone

def apply_options_bad(options, memory):
    if "shrink_memory" in options:          # an option honoured first...
        memory = {a: v for a, v in memory.items() if a < options["shrink_memory"]}
    policy = load_policy(memory, 0x9000)
    if policy is None:                      # BUG: missing policy = no limits
        return sorted(o for o in options if o != "shrink_memory")
    return sorted(o for o in options if o not in DANGEROUS | {"shrink_memory"})

def apply_options_good(options, memory):
    policy = load_policy(memory, 0x9000)    # FIX 1: read policy before options
    if policy is None:
        raise SystemExit("refuse to boot: Secure Boot policy missing")  # FIX 2
    return sorted(o for o in options if o not in DANGEROUS | {"shrink_memory"})

memory = {0x1000: "boot app", 0x9000: "SB policy: no test signing"}
opts = {"shrink_memory": 0x8000, "allow_unsigned": 1}
print("bad :", apply_options_bad(opts, memory))
print("good:", apply_options_good(opts, memory))

