U32 = 0xFFFFFFFF

def alloc_size_bad(width, height):
    row = (width * 2) & U32
    return (row * height) & U32

def alloc_size_good(width, height):
    if not (0 < width <= 8192 and 0 < height <= 8192):
        raise ValueError("dimensions out of range")
