# Toy model of the integer-overflow bug class Binarly reported in a PNG
# parser: a 32-bit size computed from an attacker-chosen width.
U32 = 0xFFFFFFFF
MAX_W, MAX_H = 8192, 8192            # a real screen is far smaller

def alloc_size_bad(width, height):
    row = (width * 2) & U32           # C uint32 arithmetic wraps silently
    return (row * height) & U32

def alloc_size_good(width, height):
    if not (0 < width <= MAX_W and 0 < height <= MAX_H):
        raise ValueError("refuse: dimensions out of range")
    size = width * 2 * height         # Python ints never wrap
    if size > U32:
        raise ValueError("refuse: size overflows 32 bits")
    return size

for w, h in [(640, 480), (0x80000200, 1)]:
    need = w * 2 * h                  # bytes the decoder will write
    bad = alloc_size_bad(w, h)
    try:
        good = hex(alloc_size_good(w, h))
    except ValueError as e:
        good = str(e)
    print(f"width={w:#x}: writes {need:#x} bytes, bad alloc={bad:#x}, good={good}")

# Toy model of CVE-2024-7344's bug class: a signed app that loads the next
# stage with its own loader instead of the firmware's verified LoadImage().
import hashlib
DB = {hashlib.sha256(b"vendor-recovery-v2").hexdigest()}   # allowed hashes
DBX = set()

def firmware_load_image(blob):        # stands in for UEFI LoadImage()
    h = hashlib.sha256(blob).hexdigest()
    if h in DBX or h not in DB:
        raise PermissionError("Secure Boot violation")
    return f"running {blob.decode()}"

def custom_loader_bad(blob):           # BUG: maps and runs, never verifies
    return f"running {blob.decode()}"

def custom_loader_good(blob):          # FIX: hand every stage to the firmware
    return firmware_load_image(blob)

for blob in (b"vendor-recovery-v2", b"unsigned-payload"):
    try:
        good = custom_loader_good(blob)
    except PermissionError as e:
        good = str(e)
    print(f"{blob.decode():18} bad: {custom_loader_bad(blob):26} good: {good}")

import hmac, hashlib
# Toy: an HMAC stands in for the vendor's public-key signature.
VENDOR_KEY = b"made-up vendor key"
def sign(img): return hmac.new(VENDOR_KEY, img["body"], hashlib.sha256).digest()

def make(version, svn):
    body = f"firmware v{version} svn={svn}".encode()
    img = {"version": version, "svn": svn, "body": body}
    img["sig"] = sign(img)
    return img

installed_svn = 4                    # stored in protected flash, only rises
v12 = make("1.2", 3)                 # authentic, but has a known hole
v15 = make("1.5", 4)
forged = dict(v15, body=b"firmware v1.5 + implant")

def update_bad(img):                 # BUG: authentic is not the same as safe
    return hmac.compare_digest(sign(img), img["sig"])

def update_good(img):
    global installed_svn
    if not hmac.compare_digest(sign(img), img["sig"]):
        return "rejected: bad signature"
    if img["svn"] < installed_svn:
        return "rejected: rollback below SVN %d" % installed_svn
    installed_svn = max(installed_svn, img["svn"])
    return "installed"

for name, img in [("forged 1.5", forged), ("old 1.2", v12), ("new 1.5", v15)]:
    print(f"{name:10} bad={update_bad(img)!s:5} good={update_good(img)}")
